import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import '../App.css';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const EmployeeDashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [vacationDays, setVacationDays] = useState(0);
  const [hasCheckedIn, setHasCheckedIn] = useState(false);
  const [hasCheckedOut, setHasCheckedOut] = useState(false);
  const [loading, setLoading] = useState(false);
  const [selectedDates, setSelectedDates] = useState([]);
  const [showCalendar, setShowCalendar] = useState(false);
  const [locationError, setLocationError] = useState(null);
  const [usedDates, setUsedDates] = useState([]);
  const [newNotifications, setNewNotifications] = useState(0);

  // [Mantener todos los useEffect y funciones iguales hasta el return...]

  return (
      <div className="min-h-screen bg-gray-100 p-4 md:p-8">
        <div className="max-w-md mx-auto bg-white rounded-xl shadow-md overflow-hidden p-6 space-y-6">
          {/* Encabezado */}
          <div className="text-center">
            {user && (
                <h1 className="text-2xl font-bold text-gray-800 mb-2">
                  Bienvenido, {user.name}
                </h1>
            )}
            <p className="text-lg text-gray-600">
              Días disponibles: <span className="font-bold text-blue-600">{vacationDays}</span>
            </p>
          </div>

          {/* Check-in/out */}
          <div className="space-y-4">
            {!hasCheckedIn && !hasCheckedOut && (
                <div className="space-y-2">
                  <button
                      onClick={() => handleCheck('checkin')}
                      disabled={loading}
                      className={`w-full py-3 rounded-lg font-medium transition-colors ${
                          loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-green-500 hover:bg-green-600 text-white'
                      }`}
                  >
                    {loading ? 'Cargando...' : 'Registrar Check-in'}
                  </button>
                  {locationError && (
                      <div className="p-3 bg-red-50 rounded-lg text-red-600 text-sm">
                        {locationError}
                        <button
                            onClick={() => handleCheck('checkin')}
                            className="ml-2 text-blue-600 hover:underline"
                        >
                          Reintentar
                        </button>
                      </div>
                  )}
                </div>
            )}

            {hasCheckedIn && !hasCheckedOut && (
                <div className="space-y-2">
                  <button
                      onClick={() => handleCheck('checkout')}
                      disabled={loading}
                      className={`w-full py-3 rounded-lg font-medium transition-colors ${
                          loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-red-500 hover:bg-red-600 text-white'
                      }`}
                  >
                    {loading ? 'Cargando...' : 'Registrar Check-out'}
                  </button>
                  {locationError && (
                      <div className="p-3 bg-red-50 rounded-lg text-red-600 text-sm">
                        {locationError}
                        <button
                            onClick={() => handleCheck('checkout')}
                            className="ml-2 text-blue-600 hover:underline"
                        >
                          Reintentar
                        </button>
                      </div>
                  )}
                </div>
            )}
          </div>

          {/* Vacaciones */}
          <div className="space-y-4">
            <button
                onClick={() => setShowCalendar(!showCalendar)}
                disabled={vacationDays === 0}
                className={`w-full py-3 rounded-lg font-medium transition-colors ${
                    vacationDays > 0
                        ? 'bg-blue-500 hover:bg-blue-600 text-white'
                        : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                }`}
            >
              Solicitar Vacaciones
            </button>

            {showCalendar && (
                <div className="p-4 bg-gray-50 rounded-lg">
                  <h2 className="text-lg font-bold mb-3 text-center">Selecciona tus días</h2>
                  <p className="text-sm text-gray-600 text-center mb-4">
                    Seleccionados: <strong>{selectedDates.length}</strong> {selectedDates.length === 1 ? 'día' : 'días'}
                  </p>

                  <div className="flex justify-center">
                    <Calendar
                        onClickDay={handleDateChange}
                        selectRange={false}
                        tileDisabled={tileDisabled}
                        view="month"
                        className="border-0 w-full"
                        tileClassName={({ date, view }) => {
                          if (view !== 'month') return null;
                          const dateString = date.toISOString().split('T')[0];
                          return selectedDates.includes(dateString)
                              ? 'bg-blue-500 text-white rounded-full'
                              : null;
                        }}
                    />
                  </div>

                  <div className="flex justify-center gap-3 mt-4">
                    <button
                        onClick={() => setSelectedDates([])}
                        className="px-4 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400"
                    >
                      Limpiar
                    </button>
                    <button
                        onClick={handleVacationRequest}
                        className="px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600"
                    >
                      Enviar
                    </button>
                  </div>
                </div>
            )}
          </div>

          {/* Otros botones */}
          <div className="space-y-3">
            <button
                onClick={() => navigate('/employee/vacation-status')}
                className="w-full py-3 bg-purple-500 hover:bg-purple-600 text-white rounded-lg font-medium relative"
            >
              Ver Solicitudes
              {newNotifications > 0 && (
                  <span className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs">
                {newNotifications}
              </span>
              )}
            </button>

            <button
                onClick={handleLogout}
                className="w-full py-3 bg-gray-600 hover:bg-gray-700 text-white rounded-lg font-medium"
            >
              Cerrar Sesión
            </button>
          </div>
        </div>
      </div>
  );
};

export default EmployeeDashboard;
